// Editorial definitions, not promises of delivery, platform eligibility or prices.
const topicRows: [string, string, string, string, string, string, string][] = [
  ["digital-marketing", "Digital Marketing", "Digital marketing connects search, paid advertising, social content and permission-based follow-up to help a business attract and convert customers online.", "Define the offer, research customer questions, select acquisition channels and connect enquiries to sales follow-up.", "Qualified enquiries, acquisition cost, completed sales and repeat purchases by channel.", "Opening every advertising channel at once makes it difficult to learn which offer and audience work.", "Compare an integrated plan with a focused single-channel test before committing to a large retainer."],
  ["google-ads", "Google Ads", "Google Ads places paid advertisements across Google's advertising inventory. Search campaigns can reach people actively looking for a product or service; other campaign types serve different discovery and conversion goals.", "Check search intent, build relevant ad groups, review negative keywords, write accurate ads and verify landing-page conversion tracking.", "Search terms, conversion rate, cost per qualified lead and sales attributed to the campaign.", "Clicks are not sales. Broad or irrelevant search terms can spend the budget without producing suitable enquiries.", "Choose search when customers already describe your service in searches; compare display or video when the priority is discovery."],
  ["facebook-marketing", "Facebook Marketing", "Facebook marketing combines page content, community conversations and optional paid promotion. Organic publishing builds a useful brand presence, while paid campaigns have separate objectives and budgets.", "Plan useful posts, maintain page information, organise inbox responses and separate organic reporting from paid advertising.", "Relevant engagement, meaningful messages, referred website visits and qualified enquiries.", "Boosting every post without a conversion goal can produce reactions without customer demand.", "Decide whether you need ongoing page management, paid lead generation or both; they are different scopes of work."],
  ["instagram-marketing", "Instagram Marketing", "Instagram marketing uses visual posts, Stories, Reels and audience conversations to communicate a brand's offer. Paid promotion is a separate way to distribute content beyond existing followers.", "Develop product demonstrations, useful captions, visual consistency, profile information and an enquiry response process.", "Content saves, relevant profile visits, messages, website conversions and sales rather than follower count alone.", "Attractive imagery cannot resolve an unclear offer, missing delivery details or unanswered customer messages.", "Choose a visual content plan when customers benefit from seeing the product, process or finished result."],
  ["tiktok-marketing", "TikTok Marketing", "TikTok marketing centres on short-form video, creator collaboration and audience interaction. Paid advertising requires an additional check of current account, billing and targeting eligibility.", "Research audience questions, script a clear opening, film original demonstrations and review watch behaviour before repeating successful formats.", "Video retention, relevant comments, profile visits and tracked enquiries from the content.", "Do not assume Sri Lankan self-service advertising availability, currency support or targeting options without checking the current account.", "Compare organic video and creator partnerships with paid ads only after verifying the account's available options."],
  ["linkedin-marketing", "LinkedIn Marketing", "LinkedIn marketing helps a business share professional expertise and build conversations with buyers, partners and prospective employees. Company-page activity and individual professional posts serve different roles.", "Define buyer roles, publish useful industry explanations, coordinate staff contributions and establish a professional follow-up process.", "Relevant conversations, target-account engagement, qualified meetings and opportunities created.", "High impressions from people outside the buying audience can hide weak commercial relevance.", "Consider LinkedIn for professional or B2B offers where role, industry and buying context matter."],
  ["youtube-marketing", "YouTube Marketing", "YouTube marketing uses videos to answer customer questions, explain products and build a searchable library. Organic channel development is distinct from buying video-ad distribution.", "Plan topic-led videos, write accurate titles, add useful descriptions and organise related videos into a customer learning journey.", "Audience retention, returning viewers, relevant search traffic and website or enquiry actions.", "A large view count does not prove that viewers understand the offer or intend to purchase.", "Choose longer explanations when customers need demonstrations, comparisons or evidence before enquiring."],
  ["ppc", "PPC Advertising", "Pay-per-click advertising is a buying model in which advertisers pay for clicks. Search advertising is a common example, but the buying model is not the same as a complete marketing strategy.", "Agree the conversion goal, control targeting and bids, check destination quality and review spend alongside enquiry quality.", "Click-through rate, landing-page conversion rate, cost per enquiry and cost per customer.", "Optimising only for a lower click cost can attract cheaper but less relevant traffic.", "Compare PPC's measurable testing costs with organic acquisition work and the value of a converted customer."],
  ["display-advertising", "Display Advertising", "Display advertising places visual advertisements on websites and apps through ad networks or publisher agreements. It is usually evaluated differently from high-intent search traffic.", "Prepare placement-appropriate artwork, select audience and inventory controls, agree exclusions and check destination behaviour.", "Reach, frequency, viewable impressions and assisted or direct conversions with attribution clearly stated.", "Poor placements and repeated exposure can waste spend; impressions alone are not evidence of customer interest.", "Use display for discovery or re-engagement and compare its contribution with search-led enquiries."],
  ["remarketing", "Remarketing", "Remarketing reconnects with people who previously interacted with a business, where the platform supports eligible audiences and lawful data use.", "Separate recent visitors from customers, define audience windows, exclude completed buyers where appropriate and match messages to the next step.", "Returning-visitor conversions, frequency, audience size and incremental contribution rather than total attributed sales alone.", "Audience eligibility and consent matter. Small lists or excessive repetition can limit performance.", "Add remarketing when there is enough relevant prior traffic and a useful reason for the visitor to return."],
  ["programmatic-advertising", "Programmatic Advertising", "Programmatic advertising uses automated systems to buy advertising inventory against agreed targeting and buying rules. It requires clear control over inventory quality, fees and measurement.", "Specify audience criteria, brand-safety exclusions, buying fees, placement reporting and independent measurement where available.", "Viewability, frequency, invalid traffic, qualified reach and downstream conversions.", "A low impression price can hide unsuitable inventory, unclear fees or weak audience quality.", "Compare a managed programmatic buy with a simpler network campaign when budget or measurement resources are limited."],
  ["lead-generation", "Lead Generation", "Lead generation captures interest from potential customers through forms, calls, messages or other enquiry actions. A submitted lead becomes valuable only when it fits the offer and can be followed up.", "Define a qualified lead, design a clear offer, limit unnecessary form fields and connect each enquiry to a responsible follow-up owner.", "Qualified-lead rate, contactability, appointments, opportunities and completed sales.", "Counting all form submissions equally can disguise spam, duplicates and people outside the service area.", "Choose the qualification criteria before choosing an advertising channel or purchasing a lead-generation package."],
  ["performance-marketing", "Performance Marketing", "Performance marketing evaluates campaigns against defined actions such as qualified leads or sales. It relies on reliable measurement and commercial targets, not simply on an advertising platform's reported results.", "Set a measurable outcome, agree attribution, test offers and creatives, and feed sales outcomes back into campaign decisions.", "Customer acquisition cost, contribution after campaign costs, qualified enquiries and sales conversion.", "Revenue is not profit, and reported return on ad spend can omit fees, returns and operating costs.", "Use a performance-led plan when the business can reliably connect enquiries or purchases to commercial outcomes."],
  ["linkedin-ads", "LinkedIn Ads", "LinkedIn Ads is paid advertising on LinkedIn, with campaign options and professional targeting controlled by the platform and account eligibility.", "Define buying roles and industries, prepare a focused offer, review form qualification and align follow-up with the longer B2B sales cycle.", "Cost per qualified enquiry, target-account fit, meeting rate and sales opportunities.", "A filled lead form is not automatically a decision-maker or an approved purchasing opportunity.", "Compare audience fit and customer value with paid search before deciding how much budget to allocate."],
  ["google-shopping", "Google Shopping", "Google Shopping-related campaigns use structured product information to help eligible products appear in supported shopping experiences. Country, feed and campaign eligibility must be confirmed before launch.", "Audit product titles, images, identifiers, availability, shipping information and destination policies against current Merchant Center requirements.", "Feed approvals, product-level conversions, advertising cost and margin after returns and delivery.", "Do not promise Shopping ads for a country or account without checking current supported markets and programme requirements.", "Start with feed and market eligibility; if unsupported, compare eligible search campaigns or other product-ad channels."],
  ["content-marketing", "Content Marketing", "Content marketing creates useful material that answers customer questions before and after purchase. It supports search, social distribution, email and sales conversations when tied to real audience needs.", "Map customer questions, gather product evidence, prepare an editorial brief and connect each piece to a relevant next step.", "Useful search traffic, engaged reading, assisted enquiries and the contribution of content to customer decisions.", "Publishing longer text or repeating keywords does not make an answer more useful or guarantee rankings.", "Choose topics where you can add accurate product details, first-hand explanations or practical comparisons."],
  ["reputation-management", "Reputation Management", "Online reputation management organises how a business monitors and responds to reviews, complaints and public information. It is not a promise to erase criticism or remove legitimate reviews.", "Monitor relevant channels, verify facts, create response guidelines and route service problems to someone who can resolve them.", "Response time, resolved issues, recurring complaint themes and accuracy of public business information.", "Fake reviews, incentives for misleading feedback and unsupported removal promises can damage trust.", "Prioritise service resolution and honest responses before considering broader reputation campaigns."],
  ["email-marketing", "Email Marketing", "Email marketing sends relevant messages to subscribers and customers who have given appropriate permission. It can support education, promotions and retention when list quality and relevance are maintained.", "Audit permission, segment contacts, verify sender authentication, create focused messages and test links and unsubscribe handling.", "Delivered messages, clicks, replies, unsubscribes and confirmed conversions; open rates can be affected by privacy features.", "Purchased lists and irrelevant repeated mail can harm deliverability and customer trust.", "Choose email when you have a legitimate audience relationship and useful information to send, not just a large contact file."],
  ["mobile-app-advertising", "In-App & Mobile Advertising", "In-app advertising reaches users inside mobile applications through supported networks and placements. Advertising inside another app differs from promoting installations of your own app.", "Clarify the objective, choose suitable formats, agree placement exclusions and test the destination on a mobile connection.", "Quality visits, completed conversions, placement performance and, for app acquisition, meaningful post-install actions.", "Accidental taps and weak mobile landing pages can inflate clicks without producing customers.", "Decide whether you need mobile reach, leads or app acquisition before comparing networks."],
  ["podcast-advertising", "Podcast Advertising", "Podcast advertising places a host-read message or produced advertisement within audio programming. Audience fit and delivery evidence matter more than the popularity of a show in isolation.", "Review the show's audience, agree script approval, placement dates, reuse rights and a trackable listener offer.", "Confirmed delivery, tracked visits or codes, listener enquiries and changes in relevant branded demand.", "Downloads and listens are not interchangeable with verified customers or unique people reached.", "Choose shows whose subject, language and listener needs align with the offer."],
  ["native-advertising", "Native Advertising", "Native advertising is paid promotion designed to fit a publisher or platform's surrounding format. Sponsored content must remain recognisable as advertising rather than disguised independent advice.", "Agree sponsorship disclosure, audience fit, editorial boundaries, destination quality and campaign tracking.", "Engaged visits, relevant reading, qualified enquiries and placement-level conversions.", "Sensational headlines can attract clicks while undermining trust or violating publisher policies.", "Use native placements when a useful explanation needs distribution to a relevant publisher audience."],
  ["referral-marketing", "Referral Marketing", "Referral marketing encourages existing customers or contacts to recommend an offer under clearly stated programme rules.", "Define eligible referrals, rewards, exclusions, referral tracking and how disputes or cancellations affect qualification.", "Verified referred customers, reward costs, repeat purchases and programme abuse.", "Unclear rules, duplicate referrals or rewards issued before a qualifying purchase can undermine the programme.", "Compare the reward with customer value and choose an offer customers can honestly recommend."],
  ["affiliate-marketing", "Affiliate Marketing", "Affiliate marketing rewards approved partners for qualifying actions under an agreed commission and attribution model. It still involves programme, content and tracking costs.", "Set commission terms, approve partner methods, require disclosures and define validation, returns and payout rules.", "Validated sales, net contribution, partner quality, cancellations and commission cost.", "Last-click attribution can reward a partner for a sale that would have happened anyway; fraud controls are essential.", "Choose affiliates when the margin and fulfilment process can support commissions on verified outcomes."],
  ["chatbot-marketing", "Chatbot Marketing", "Chatbot marketing automates defined customer conversations on a website or supported messaging channel. Effective flows provide clear choices and a reliable hand-off to a person.", "Map common questions, verify answers, collect only necessary details and test escalation when the bot cannot help.", "Resolved conversations, qualified hand-offs, abandonment and time to human response.", "An automated answer must not invent prices, availability or guarantees, or trap customers without human help.", "Start with repeatable questions and simple qualification before expanding to complex or AI-generated responses."],
  ["push-notification-advertising", "Push Notification Campaigns", "Push notification campaigns send short messages to users who have enabled the relevant browser or app permission.", "Clarify the permission request, segment by useful behaviour, limit frequency and provide accessible notification settings.", "Opt-in quality, clicks, repeat visits, conversions and disabled permissions.", "Repeated irrelevant messages can prompt users to withdraw permission rather than return.", "Use push for timely, genuinely useful updates rather than as a replacement for a complete customer relationship."],
  ["social-media-marketing", "Social Media Marketing", "Social media marketing combines relevant content, community engagement and optional paid distribution. Strategy starts with the customer and offer rather than a fixed number of posts.", "Choose audience-relevant platforms, agree content themes, separate paid budgets and establish approvals and response ownership.", "Qualified messages, meaningful engagement, referred traffic and sales-related actions.", "Organic content, advertising and customer service are different responsibilities and should not be hidden in one vague package.", "Compare content management with paid campaigns according to whether the priority is trust, discovery or immediate enquiries."],
  ["social-media-management", "Social Media Management", "Social media management is the ongoing planning, approval, publishing and moderation of a business's social presence. Paid ad management may be quoted separately.", "Set a content calendar, define approval deadlines, maintain channel access and agree comment and inbox escalation.", "Publishing consistency, relevant engagement, response time and qualified conversations.", "A package counted only in posts can omit video production, revisions, moderation or paid media.", "Ask who creates the content, who approves it and who responds to potential customers."],
  ["facebook-ads", "Facebook Ads", "Facebook Ads are paid placements managed through Meta's advertising tools. Campaign objectives and destinations should reflect the action a business wants customers to take.", "Choose a conversion goal, prepare audience-appropriate creative, check account access and verify enquiry or purchase tracking.", "Cost per qualified message or lead, enquiry quality, follow-up rate and completed sales.", "A low cost per message can be misleading when conversations are irrelevant or never receive a response.", "Compare website leads, platform forms and messaging destinations based on qualification and follow-up capacity."],
  ["instagram-ads", "Instagram Ads", "Instagram Ads distribute paid creative in eligible Instagram placements. They are different from organic posts and should have a clear conversion goal.", "Prepare placement-appropriate creative, align the offer and destination, test mobile journeys and review results by format.", "Qualified messages, landing-page conversions and cost per customer alongside relevant engagement.", "Reusing an unsuitable cropped design can hide the offer or important product details.", "Choose placements and formats that show the product clearly and make the next customer action straightforward."],
  ["tiktok-ads", "TikTok Ads", "TikTok Ads is paid distribution through TikTok's business advertising tools, subject to current advertiser, billing and location-targeting availability.", "Verify account eligibility first, prepare original video, check destination quality and confirm supported conversion measurement.", "Qualified visits, conversions, audience retention and actual sales outcomes.", "An agency account or targeting feature available elsewhere does not establish self-service availability for a Sri Lankan business.", "Check current platform eligibility before budgeting; organic content and creator campaigns remain separate options."],
  ["youtube-ads", "YouTube Ads", "YouTube Ads uses paid video distribution through Google's advertising products. Creative, targeting and measurement should fit whether the campaign is for awareness, consideration or conversions.", "Prepare a clear opening, verify creative rights, select suitable audiences and connect the video to a relevant destination.", "Relevant reach, view behaviour, qualified visits and conversions with attribution windows stated.", "Video views alone do not establish sales, and view-through attribution should not be treated as a confirmed causal result.", "Match the video's message and length to the buying stage rather than promoting a general company film to everyone."],
  ["influencer-marketing", "Influencer Marketing", "Influencer marketing works with creators to communicate an offer to their audience under agreed content, disclosure and usage terms.", "Check audience relevance, brief factual claims, agree sponsorship disclosure and document publishing dates and content reuse rights.", "Audience fit, verified delivery, tracked enquiries or codes and reusable content value.", "Follower totals can hide irrelevant audiences; creator content cannot be reused indefinitely without the agreed rights.", "Choose creators for audience trust and content fit, not only popularity."],
  ["social-media-agency", "Choosing a Social Media Agency", "Choosing a social media agency involves comparing strategy, content quality, advertising management, reporting and account ownership against the business's actual needs.", "Request a clear proposal separating platform scope, creative production, moderation, paid media and reporting responsibilities.", "Quality of relevant enquiries, accountable delivery and transparent reporting against agreed goals.", "Avoid proposals built around guaranteed followers or unclear access to accounts and campaign data.", "Compare sample work relevant to your offer, ask about approval and exit terms, and retain ownership of business accounts."],
  ["seo-services", "SEO Services", "SEO improves how a website can be crawled, understood and used for relevant organic searches. It combines technical accessibility, useful content and legitimate signals of trust.", "Review indexing, search intent, site structure, content evidence and conversion paths before prioritising changes.", "Relevant non-brand search traffic, indexed priority pages, qualified enquiries and conversions.", "No provider can guarantee first place or inclusion in an AI-generated answer; purchased ranking links can violate search policies.", "Compare a technical audit, local visibility work and content improvement according to the site's actual constraints."],
  ["local-seo", "Local SEO", "Local SEO improves visibility for searches connected to a business location or service area. Accurate business information and genuinely useful local pages support customer decisions.", "Review eligible Business Profile details, address or service-area accuracy, opening information, reviews and local landing pages.", "Relevant local searches, website enquiries, calls and direction requests where available.", "Creating fake locations or near-identical city pages is not a substitute for a real local offering.", "Start with accurate eligibility and business details, then address the questions customers ask in each served area."],
  ["technical-seo", "Technical SEO", "Technical SEO addresses the site's crawlability, indexing controls and technical presentation so search engines can access intended public content.", "Inspect status codes, robots controls, canonicals, redirects, internal links, mobile usability and important rendered content.", "Indexing of intended pages, crawl errors, valid canonical choices and improvements in priority-page accessibility.", "An audit score does not show commercial impact; changes should target issues affecting useful pages.", "Prioritise blocked or broken customer journeys and indexing problems before cosmetic tool recommendations."],
  ["ecommerce-seo", "Ecommerce SEO", "Ecommerce SEO helps customers discover and understand product and category pages through organic search.", "Improve category structure, original product details, stock information, crawl controls for filters and accurate product structured data.", "Organic product visits, conversion rate, revenue and availability of important category pages in search.", "Duplicate supplier descriptions and uncontrolled filter URLs can distract crawlers and customers from useful pages.", "Prioritise categories and products with real demand, availability and sufficient information to make a buying decision."],
  ["backlink-services", "Backlink Strategy", "A backlink strategy earns relevant references from other websites by making useful material and genuine business relationships discoverable.", "Review existing link quality, identify relevant publications and develop original resources worth referencing.", "Relevant referral traffic, editorial mentions and broader organic performance rather than raw link totals.", "Buying links that pass ranking credit, automated link schemes and guaranteed ranking packages can violate Google's spam policies.", "Choose editorial relevance and legitimate coverage rather than the largest number of links."],
  ["seo-company", "Choosing an SEO Company", "Comparing SEO companies means assessing diagnosis, proposed work, reporting and accountability rather than accepting a ranking guarantee.", "Request a site-specific audit, prioritised recommendations, ownership arrangements and explanations of content and link methods.", "Progress on agreed fixes, relevant traffic and customer actions rather than isolated ranking screenshots.", "A provider should explain risks and dependencies instead of promising a fixed position on Google.", "Ask for evidence relevant to your type of site and an implementation plan that distinguishes advice from completed work."],
  ["seo", "Search Engine Optimisation", "Search engine optimisation makes relevant website content easier to find, understand and use in organic search. It is an ongoing improvement process, not paid placement.", "Match each useful page to customer intent, fix indexing obstacles and provide accurate information supported by real evidence.", "Relevant search clicks, qualified enquiries and conversion contribution over a meaningful comparison period.", "Ranking depends on competition and search systems as well as the site's work; there is no universal completion date.", "Start with the pages that answer important customer questions and make the next step easy."],
  ["email-sms-marketing", "Email, SMS & WhatsApp Marketing", "Direct digital marketing uses permitted email, SMS or WhatsApp conversations to communicate useful offers and updates to a known audience.", "Choose channels by message purpose, document permission, set suppression rules and assign responsibility for customer replies.", "Delivered messages, clicks, replies, opt-outs and confirmed customer actions across each channel.", "Channel rules and pricing differ; promotional messages should not be disguised as necessary service notifications.", "Compare audience permission, message urgency, available content and reply handling before choosing a channel."],
  ["bulk-email", "Bulk Email", "Bulk email distributes a message to a selected subscriber segment through an email platform. Volume alone is not a measure of effective marketing.", "Validate permission and addresses, authenticate the sender, segment the audience and test the unsubscribe path.", "Delivery failures, spam complaints, clicks and conversions from delivered messages.", "Sending to purchased or stale addresses can harm sender reputation and increase complaints.", "Prioritise a clean, relevant list before buying a higher sending allowance."],
  ["email-automation", "Email Automation", "Email automation sends a defined sequence when a subscriber reaches an agreed event or stage, such as signup or a relevant purchase follow-up.", "Map triggers, delays, exit conditions and suppression rules; test what happens when a customer buys or unsubscribes.", "Sequence completion, relevant conversions, unsubscribes and mistakes such as duplicate or obsolete messages.", "An automation without exit rules may continue promoting something a customer already bought.", "Automate a proven, useful customer journey before introducing many overlapping sequences."],
  ["b2b-email-marketing", "B2B Email Marketing", "B2B email marketing communicates useful business information to appropriately permissioned professional contacts and supports a considered sales conversation.", "Segment by buyer role and need, write specific business-value messages and connect interested replies to a responsible salesperson.", "Relevant replies, qualified meetings, opportunities and unsubscribes rather than opens alone.", "A job title or public email address does not remove the need to consider permission, privacy and applicable rules.", "Choose a narrow buyer problem and a clear next step rather than a generic mass introduction."],
  ["sms-marketing", "SMS Marketing", "SMS marketing sends concise promotional or service messages through a messaging provider under the applicable permission and sender requirements.", "Agree message purpose, check sender setup, review character encoding and confirm opt-out and link tracking arrangements.", "Delivered message segments, tracked visits, enquiries and opt-outs.", "Unicode characters or long messages can change the billed segment count; a delivery receipt is not proof of reading.", "Compare the full cost per delivered campaign and the customer's need for a timely message."],
  ["bulk-sms", "Bulk SMS", "Bulk SMS distributes a short message to a defined contact audience through a messaging service. Quality depends on relevance, permission and delivery controls.", "Clean contacts, check permission, test message encoding, agree sending windows and review failed numbers.", "Delivered segments, tracked customer actions, failures and opt-outs.", "The advertised unit price may not reflect multipart messages, setup charges or all provider costs.", "Ask for a sample delivery report and an itemised quotation before a large send."],
  ["whatsapp-marketing", "WhatsApp Marketing", "WhatsApp marketing uses the Business App or Business Platform for appropriate customer conversations. Platform-initiated messages must follow current template, permission and messaging rules.", "Verify opt-in, choose the appropriate product, prepare approved templates where required and route replies to a real person.", "Delivered conversations, qualified replies, appointments, opt-outs and sales outcomes.", "Unsolicited mass messaging can violate platform rules; current template and pricing rules must be checked before launch.", "Compare manual customer conversations with platform automation based on audience size and support needs."],
];

const topics = new Map(topicRows.map(([key, label, answer, scope, measure, caution, decision]) => [key, { label, answer, scope, measure, caution, decision }]));

const blogFocus: Record<string, [string, string]> = {
  "best-time-to-run-facebook-ads-in-sri-lanka": ["Finding the right schedule from your own results", "There is no verified universal best hour for every Sri Lankan advertiser. Compare qualified enquiries and sales by time in your own account, check the reporting timezone and whether staff can reply, and test a schedule without changing other major campaign settings at the same time."],
  "digital-marketing-vs-traditional-advertising": ["Comparing reach, context and response", "Traditional and digital channels can both support discovery or demand, but their buying and measurement systems differ. Compare the audience, media context, creative requirements and customer response path. Do not assume a fixed percentage split, universal entry price or that one channel always creates more trust."],
  "google-business-profile-setup-guide": ["Checking profile eligibility and ownership", "Check the official Business Profile eligibility rules before creating a listing. Use the real business name and correct address or service-area setup, retain owner access and follow the verification method Google offers. Keep hours and contact information accurate; do not promise verification or map-ranking timelines."],
  "how-to-get-on-first-page-of-google": ["Diagnosing search visibility before promising a result", "Check whether the intended pages are accessible and indexed, whether their content meets the customer's search intent and whether internal links lead to the right service. Prioritise specific fixes and useful information. Neither a first-page position nor a fixed ranking timeline can be guaranteed."],
  "sinhala-vs-tamil-vs-english-advertising-language": ["Researching language preference without stereotypes", "Choose language using actual customer conversations, service areas and content comprehension. Do not infer purchasing power from language or assume fixed advertising cost differences. Review translations with fluent readers, preserve the offer's meaning and compare qualified responses from language variants."],
  "youtube-video-marketing": ["Connecting video topics to customer decisions", "Build videos around demonstrations, comparisons and real buyer questions. Use accurate titles and captions and link to the relevant product or service. Keep organic channel learning separate from paid video-ad distribution and avoid interpreting every view as a potential buyer."],
  "digital-marketing": ["Choosing a practical channel mix", "List the questions customers ask before buying and separate people discovering the offer from people actively looking for it. Use one primary acquisition test and one follow-up process, then expand only when the results can be explained."],
  "online-marketing": ["Connecting discovery to a sale", "Trace the journey from a search result or social post to the offer page, enquiry and sales response. A customer should see consistent product details, service areas and next steps throughout that journey."],
  "internet-marketing": ["Building the foundations before promotion", "Check the mobile website, business information, useful service pages and enquiry handling before buying traffic. A working customer journey is more valuable than accounts on every available platform."],
  "digital-advertising": ["Comparing paid channel roles", "Search can capture an expressed need, while visual and video placements can introduce an unfamiliar offer. Compare them by buying stage and customer outcome rather than treating every click as equivalent."],
  "social-media-advertising": ["Choosing the campaign destination", "Compare messaging, platform lead forms and website conversions. Messaging needs fast responses; forms need qualification; website journeys need clear pages and verified tracking. Choose the destination your team can actually support."],
  "facebook-advertising": ["Testing the offer before scaling", "Build a small set of genuinely different messages around customer needs. Review whether conversations are relevant before increasing spend; cheap replies alone do not justify a larger campaign."],
  "instagram-advertising": ["Matching creative to buying questions", "Use demonstrations, product details and clear captions rather than relying only on a polished image. Confirm that the landing page explains availability, fulfilment and the customer's next action."],
  "tiktok-advertising": ["Verifying eligibility before account setup", "Confirm current advertiser and location-targeting availability in official TikTok guidance and the actual account. Do not select a different business country merely to bypass an unavailable local setup; compare organic and creator options separately."],
  "google-advertising": ["Reading search terms and conversions", "A keyword is a targeting input, while a search term is what someone actually searched. Review real search terms, exclude irrelevant intent and check whether conversions represent genuine customer enquiries."],
  "search-engine-marketing": ["Coordinating paid and organic search", "Compare paid search tests with organic service-page improvements. Share findings about customer questions, but report paid clicks and organic traffic separately so that each investment remains accountable."],
  "sem": ["Distinguishing a paid test from SEO", "SEM is used differently across proposals, sometimes for paid search and sometimes for a broader search strategy. Ask the provider to specify whether the scope includes ads, SEO or both, and separate media spend from professional fees."],
  "pay-per-click": ["Understanding what a click costs", "The click price is only one input. Combine it with the rate of qualified enquiries and the rate of converted customers to assess whether the campaign can support the business's margins."],
  "retargeting": ["Segmenting returning audiences", "Distinguish product viewers, enquiry starters and existing customers where eligible data supports it. Give each group a reason to return and remove irrelevant audiences rather than showing the same reminder indefinitely."],
  "conversion-marketing": ["Diagnosing where customers drop off", "Review offer clarity, page loading, form friction and response time before increasing traffic. Change one meaningful part of the customer journey and compare the quality of resulting enquiries."],
  "digital-campaign-management": ["Setting ownership and review routines", "Document who controls accounts, approves creative, checks tracking and handles leads. Keep a record of material changes so that a report can explain what changed rather than merely listing totals."],
  "seo": ["Prioritising useful pages", "Start with the services and products customers genuinely need to understand. Check indexing and improve answers before expanding the number of pages; broad keyword coverage without useful detail is not a strategy."],
  "seo-agency": ["Comparing an SEO proposal", "Ask for examples of the site's actual problems, the proposed order of fixes and who will implement them. Separate recurring advice from deliverables and retain access to search performance data."],
  "search-engine-optimization": ["Understanding crawl, index and ranking", "A reachable page may still not be indexed, and an indexed page may not rank prominently. Diagnose these stages separately before assuming that more text or links will solve the problem."],
  "website-ranking": ["Finding the right diagnosis", "Check the intended URL, indexability, canonical selection and relevance to the search query. Then compare the page's answer with the visitor's need instead of treating a single rank-tracking result as the whole picture."],
  "google-ranking": ["Measuring visibility without guarantees", "Use real search performance trends and qualified customer actions to evaluate progress. Rankings can vary by query, location and context, so avoid decisions based only on a single screenshot."],
  "keyword-research": ["Separating search intent from volume", "Group questions by what the searcher wants to do: learn, compare, find a local provider or buy. Use Sri Lankan evidence where available; missing volume means unknown demand, not an easy ranking opportunity."],
  "on-page-seo": ["Improving the answer on the page", "Write a clear title, one descriptive main heading and useful sections that explain the actual offer. Link to relevant services and keep structured data consistent with what customers can read."],
  "off-page-seo": ["Earning relevant references", "Look for legitimate editorial coverage, business relationships and useful resources worth citing. Do not judge a link programme by volume alone or buy ranking-credit links disguised as guaranteed authority."],
  "organic-traffic": ["Separating visitors from customers", "Compare relevant non-brand searches and the actions visitors take. More sessions can be commercially weak if they come from unrelated topics or countries the business does not serve."],
  "social-media-marketing": ["Planning content around customer needs", "Group content into questions, demonstrations, proof and timely updates. Decide which posts build understanding and which support a clear enquiry action; keep paid campaigns separate in the report."],
  "social-media-campaigns": ["Building a campaign rather than a post list", "Connect one audience need, one offer and one customer action across the campaign. Prepare response handling before publishing and make each creative variation a meaningful test."],
  "reels-marketing": ["Making short videos useful", "Show one problem or product detail clearly, keep important text inside the placement's usable area and add captions where helpful. Compare retention with meaningful messages rather than treating views as sales."],
  "viral-marketing": ["Managing reach without a viral promise", "Build content people can honestly share because it is helpful, interesting or relevant. Virality cannot be guaranteed, and sudden reach requires moderation and a plan for inappropriate or off-topic reactions."],
  "community-management": ["Organising replies and escalation", "Separate routine questions, product complaints and urgent issues. Agree response ownership and escalation rules, and record recurring feedback so the business can improve the offer itself."],
  "content-creation": ["Preparing a useful production brief", "Specify the audience, claim, evidence, format, approval owner and usage rights. Original product demonstrations and accurate explanations are more valuable than a large batch of interchangeable graphics."],
  "email-marketing": ["Keeping the list relevant", "Document how contacts joined, segment by customer need and remove suppressed addresses from future campaigns. Useful messages and reliable permission handling take priority over list size."],
  "email-campaigns": ["Testing one clear message", "Choose a single primary action, verify every link and compare meaningful conversions from delivered messages. Review unsubscribes alongside clicks to understand whether the audience still wants the content."],
  "newsletter-marketing": ["Creating a reason to stay subscribed", "Build a recognisable editorial promise, such as practical product advice or relevant business updates. Balance useful information with promotions and let subscribers manage their preferences."],
  "email-advertising": ["Distinguishing subscribers from paid placements", "Clarify whether the work sends to your own permissioned list or buys space in another publisher's newsletter. Verify audience provenance, disclosure, reporting and who controls subscriber data."],
  "sms-advertising": ["Planning short messages responsibly", "Keep the sender, offer and next action understandable within the message. Confirm permission, encoding and opt-out arrangements before checking the final provider quotation."],
  "promotional-sms": ["Checking the full campaign cost", "Review the message's actual segment count, sender setup, delivery charges and destination link. Keep promotional campaigns separate from necessary service notifications and avoid messaging customers who opted out."],
  "whatsapp-advertising": ["Connecting an ad to a conversation", "Separate click-to-WhatsApp acquisition from outbound messaging to existing contacts. One attracts a new conversation; the other needs appropriate permission and compliance with current Business Platform rules."],
};

const familyAliases: Record<string, string> = {
  "best-time-to-run-facebook-ads-in-sri-lanka": "facebook-ads", "digital-marketing-vs-traditional-advertising": "digital-marketing",
  "google-business-profile-setup-guide": "local-seo", "how-to-get-on-first-page-of-google": "seo",
  "sinhala-vs-tamil-vs-english-advertising-language": "digital-marketing", "youtube-video-marketing": "youtube-marketing", "seo-pricing": "seo-services",
  "online-marketing": "digital-marketing", "internet-marketing": "digital-marketing", "digital-advertising": "digital-marketing",
  "social-media-advertising": "social-media-marketing", "facebook-advertising": "facebook-ads", "instagram-advertising": "instagram-ads",
  "tiktok-advertising": "tiktok-ads", "google-advertising": "google-ads", "search-engine-marketing": "ppc", "sem": "ppc", "pay-per-click": "ppc",
  "retargeting": "remarketing", "conversion-marketing": "performance-marketing", "digital-campaign-management": "performance-marketing",
  "seo-agency": "seo-company", "search-engine-optimization": "seo", "website-ranking": "technical-seo", "google-ranking": "seo",
  "keyword-research": "content-marketing", "on-page-seo": "seo", "off-page-seo": "backlink-services", "organic-traffic": "seo",
  "social-media-campaigns": "social-media-marketing", "reels-marketing": "instagram-marketing", "viral-marketing": "social-media-marketing",
  "community-management": "social-media-management", "content-creation": "content-marketing", "email-campaigns": "email-marketing",
  "newsletter-marketing": "email-marketing", "email-advertising": "email-marketing", "sms-advertising": "sms-marketing",
  "promotional-sms": "sms-marketing", "whatsapp-advertising": "whatsapp-marketing",
  "google-ads-cost": "google-ads", "facebook-ads-cost": "facebook-ads",
};

const categories = CATEGORIES.filter(c => ["digital-marketing-sri-lanka", "social-media-marketing-sri-lanka", "seo-services-sri-lanka", "email-sms-marketing-sri-lanka"].includes(c.slug));
const entries = categories.flatMap(c => [
  { path: c.slug, label: c.title, hub: c.slug },
  ...c.services.map(s => ({ path: s.slug, label: s.keyword, hub: c.slug })),
  ...c.blog.map(b => ({ path: `blog/${b.slug}`, label: b.keyword, hub: c.slug })),
]);
entries.push(
  { path: "seo-pricing-sri-lanka", label: "SEO Pricing", hub: "seo-services-sri-lanka" },
  ...["best-time-to-run-facebook-ads-in-sri-lanka", "digital-marketing-vs-traditional-advertising-sri-lanka", "google-business-profile-setup-guide-sri-lanka", "how-to-get-on-first-page-of-google-sri-lanka", "sinhala-vs-tamil-vs-english-advertising-language-sri-lanka", "youtube-video-marketing-sri-lanka"].map(slug => ({ path: `blog/${slug}`, label: slug.replace(/-sri-lanka$/, "").replaceAll("-", " "), hub: slug.includes("google") ? "seo-services-sri-lanka" : "digital-marketing-sri-lanka" })),
  { path: "google-ads-cost-sri-lanka", label: "Google Ads Costs", hub: "digital-marketing-sri-lanka" },
  { path: "facebook-ads-cost-sri-lanka", label: "Facebook Ads Costs", hub: "social-media-marketing-sri-lanka" },
  { path: "blog/how-to-run-tiktok-ads-in-sri-lanka-step-by-step", label: "TikTok Ads Setup", hub: "digital-marketing-sri-lanka" },
  { path: "blog/whatsapp-marketing-guide-sri-lankan-businesses", label: "WhatsApp Marketing Guide", hub: "email-sms-marketing-sri-lanka" },
);

function keyFromPath(path: string) {
  if (path.includes("how-to-run-tiktok")) return "tiktok-advertising";
  if (path.includes("whatsapp-marketing-guide")) return "whatsapp-advertising";
  return path.replace(/^blog\//, "").replace(/-sri-lanka$/, "");
}

function makeGuide(entry: typeof entries[number]): DigitalGuide | undefined {
  const key = keyFromPath(entry.path);
  const topic = topics.get(familyAliases[key] ?? key);
  if (!topic) return undefined;
  const isBlog = entry.path.startsWith("blog/");
  const isCost = key.endsWith("-cost") || key === "seo-pricing";
  const focus = blogFocus[key];
  const label = isCost ? entry.label : isBlog ? entry.label.replace(/sri lanka/gi, "").trim().replace(/\b\w/g, c => c.toUpperCase()).replace(/Seo/g, "SEO").replace(/Sem/g, "SEM").replace(/Sms/g, "SMS").replace(/Whatsapp/g, "WhatsApp").replace(/Tiktok/g, "TikTok").replace(/Youtube/g, "YouTube") : topic.label;
  const title = `${label} Sri Lanka | ${isCost ? "Budget & Fee Guide" : isBlog ? "Practical Business Guide" : "Services & Planning Guide"}`;
  const description = isCost
    ? `Understand ${label.toLowerCase()} in Sri Lanka: media spend, management fees, creative costs and qualified-lead measurement. Compare an itemised quote.`
    : `Explore ${label.toLowerCase()} in Sri Lanka: ${isBlog ? "practical steps" : "service scope"}, budget factors, measurement and common mistakes. Get clear answers and guidance.`;
  const sections = [
    {
      heading: isCost ? "What belongs in the campaign budget?" : focus?.[0] ?? `What to include in a ${label.toLowerCase()} brief`,
      paragraphs: [isCost ? "Separate the money paid to the advertising platform from management fees, creative production, landing-page work and measurement setup. Check whether tax, currency conversion or payment charges apply to the quotation. No single monthly number describes the total cost of every campaign." : focus?.[1] ?? topic.scope,
        `${topic.decision} AdvertisingSriLanka.lk is an information hub: use the options here to prepare a brief and compare suitable providers, rather than assuming every provider offers an identical package.`],
    },
    {
      heading: `Planning ${label.toLowerCase()} for Sri Lankan customers`,
      paragraphs: ["Specify the real delivery or service area, customer language and purchasing context. Sinhala, Tamil and English content should preserve the meaning of the offer rather than simply translate a slogan. Check examples, contact details and any product limitations with someone who understands the audience.",
        `For this topic, the work to discuss is: ${topic.scope} Give the provider accurate product information, approved images or footage and a named person for decisions. Test the destination on a mobile device, including form submission or messaging, before asking customers to use it.`],
    },
    {
      heading: `How to assess ${label.toLowerCase()} results`,
      paragraphs: [`Relevant measures include: ${topic.measure} Agree which actions count as genuine enquiries and which represent only early interest. Keep duplicates, spam and unsuitable locations separate from qualified demand.`,
        "For lead-based campaigns, record whether the customer could be contacted, whether the requirement matched the offer and whether the conversation progressed to a quote or sale. For online purchases, review returns and fulfilment costs before describing revenue as a profitable result. A report should explain the period, data source and attribution method."],
    },
    {
      heading: "Budget, responsibilities and provider comparison",
      paragraphs: ["Ask for an itemised scope that identifies planning, setup, content production, account management, paid distribution and reporting. Clarify which items are one-off and which recur, how revisions work and what happens when the agreement ends. A quoted fee should not silently include an unspecified advertising budget.",
        `${topic.caution} Keep business accounts and access under the business's control. Where customer data is involved, agree the purpose, access, retention and deletion process; use qualified advice for legal obligations rather than treating a marketing guide as legal clearance.`],
    },
    {
      heading: "A practical next step",
      paragraphs: [`Prepare your website or page URL, the offer, the customer area, your main objective and the way you currently handle enquiries. Include any relevant past results, but avoid sharing customer personal data in an initial brief. ${topic.decision}`,
        "Request an explanation of what should happen first, what the provider needs from you and how progress will be reviewed. Agree a manageable test or prioritised improvement plan before expanding. Examples and planning advice are not guarantees of a particular lead count, sales result, search position or AI citation."],
    },
  ];
  const faqs = [
    { q: `What is ${label.toLowerCase()} in Sri Lanka?`, a: topic.answer },
    { q: `What should I check before starting ${label.toLowerCase()}?`, a: `${topic.decision} ${topic.scope}` },
    { q: `How is the budget for ${label.toLowerCase()} calculated?`, a: "The budget depends on the objective, audience, scope and production needs. Ask for separate figures for professional fees, creative work, tools and advertising or messaging spend, including any applicable taxes or payment charges. Confirm current platform eligibility before committing." },
    { q: `How should I measure ${label.toLowerCase()} performance?`, a: `${topic.measure} Agree the data source and what counts as a qualified customer action before the work starts.` },
    { q: `What is a common mistake with ${label.toLowerCase()}?`, a: topic.caution },
    { q: `What should I send when requesting ${label.toLowerCase()} guidance?`, a: "Share your business website or social page, the product or service, customer area, preferred languages, main objective and available budget range. Explain who handles customer enquiries and what previous results you can verify." },
  ];
  if (isBlog && focus) faqs.splice(1, 0, { q: `What is the main planning priority in this ${label.toLowerCase()} guide?`, a: focus[1] });
  if (entry.hub === "seo-services-sri-lanka") faqs.push({ q: "Can SEO guarantee first place or inclusion in AI answers?", a: "No. Search engines and AI systems decide what to display. Useful accessible content, clear internal links and accurate structured data support understanding, but neither a fixed ranking nor an AI citation can be guaranteed. Google does not require special AI markup for its AI search features." });
  const sources = entry.hub === "seo-services-sri-lanka" || key === "content-marketing"
    ? [{ href: "https://developers.google.com/search/docs/fundamentals/creating-helpful-content", label: "Google: helpful, reliable, people-first content" }, { href: "https://developers.google.com/search/docs/appearance/ai-features", label: "Google: AI features and your website" }]
    : key.startsWith("tiktok") ? [{ href: "https://ads.tiktok.com/help/article/placements-available-locations", label: "TikTok: available locations and targeting" }]
    : key.includes("whatsapp") ? [{ href: "https://business.whatsapp.com/policy", label: "WhatsApp Business Messaging Policy" }]
    : key === "google-shopping" ? [{ href: "https://support.google.com/merchants/answer/160637", label: "Google Merchant Center: supported countries" }]
    : [{ href: "https://support.google.com/analytics/answer/9267568", label: "Google Analytics: understanding events and measurement" }];
  return { path: entry.path, label, title, description, answer: topic.answer, sections, faqs, sources,
    links: [
      { href: `/${entry.hub}`, label: `${categories.find(c => c.slug === entry.hub)?.title ?? "Digital Marketing"} Sri Lanka` },
      { href: "/lead-generation-sri-lanka", label: "Lead generation Sri Lanka" },
      { href: "/lead-follow-up-services-sri-lanka", label: "Lead follow-up services Sri Lanka" },
      { href: "/seo-services-sri-lanka", label: "SEO services Sri Lanka" },
    ].filter(l => l.href !== `/${entry.path}`),
  };
}

export const DIGITAL_GUIDES = new Map<string, DigitalGuide>();
for (const entry of entries) {
  const guide = makeGuide(entry);
  if (guide) DIGITAL_GUIDES.set(entry.path, guide);
}

export function getDigitalGuide(pathname: string) {
  return DIGITAL_GUIDES.get(pathname.replace(/^\/+|\/+$/g, ""));
}

export function digitalGuideSchema(guide: DigitalGuide) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "@id": `${SITE.url}/${guide.path}#digital-faqs`,
    mainEntity: guide.faqs.map(f => ({ "@type": "Question", name: f.q, acceptedAnswer: { "@type": "Answer", text: f.a } })),
  };
}